command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="5d7dc8c7a98b39ad3a6c80240d7d6f2f995bbfa9"
$branch="work/unc-network-shell-visuals-20261007"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "network visual cleanup fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before network visual cleanup"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $main){throw "network visual work branch is not accepted main"}
& git push origin --delete $branch
if($LASTEXITCODE -ne 0){throw "network visual work branch delete failed"}
& git fetch origin --prune --no-tags
if($LASTEXITCODE -ne 0){throw "network visual cleanup prune failed"}
if(& git branch -r --list ("origin/"+$branch)){throw "network visual work branch still present after prune"}
Write-Host "UNC_NETWORK_VISUAL_WORK_BRANCH_CLEANUP=PASS"
Write-Host "UNC_NETWORK_VISUAL_ACCEPTED_MAIN=$main"
